import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { DRILL_SIZE, drillOrder, sayMatches, seededRng } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { VoiceButton } from '@/components/ui/VoiceButton.js';
import { t } from '@/i18n/index.js';
import { ModeScreen, ModeSummary } from '../ModeScreen.js';
import type { ModeProps } from '../ModeRoute.js';
import { drillWords } from '../data.js';
import { missedWords, useModeRun } from '../useModeRun.js';
import styles from '../Modes.module.css';

/**
 * Say it (Pro): the meaning of one of the learner's words, and they say the
 * word. The device listens in the notebook's language through the same
 * microphone as the add sheet, and what it heard is compared leniently
 * (speech is not spelling; a recogniser's extra words are allowed).
 *
 * Practice only (card type say, source game): a recogniser's slip is not
 * evidence of memory, so no box moves. Skip moves on without an answer.
 */
export function SayIt({ view, lang, meaningLang }: ModeProps): React.JSX.Element {
  const run = useModeRun('sayIt');
  const words = useMemo(
    () =>
      drillOrder(drillWords('sayIt', view.words, lang), view.today, seededRng(run.seed)).slice(0, DRILL_SIZE),
    // A new list per run, not per answer (every answer changes the words' progress).
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [run.seed],
  );
  const [index, setIndex] = useState(0);
  const [heard, setHeard] = useState<string | undefined>(undefined);
  const [outcome, setOutcome] = useState<'correct' | 'wrong' | undefined>(undefined);
  const [problem, setProblem] = useState('');
  const shownAt = useRef(0);
  const word = words[index];

  useEffect(() => {
    shownAt.current = Date.now();
  }, [index, run.seed]);

  const onHeard = useCallback(
    (text: string) => {
      if (word === undefined || outcome !== undefined) return;
      setProblem('');
      if (text.trim() === '') {
        setProblem(t('modes.sayNothing'));
        return;
      }
      setHeard(text);
      const correct = sayMatches(text, word.headword);
      setOutcome(correct ? 'correct' : 'wrong');
      void run.record({
        wordId: word.id,
        headword: word.headword,
        correct,
        typed: text,
        latencyMs: Date.now() - shownAt.current,
      });
    },
    [word, outcome, run],
  );

  if (word === undefined) {
    return (
      <ModeSummary
        title={t('modes.sayIt')}
        lang={lang}
        score={t('modes.scoreOf', {
          right: run.answers.filter((a) => a.correct).length,
          total: run.answers.length,
        })}
        missed={missedWords(run.answers)}
        onAgain={() => {
          run.restart();
          setIndex(0);
          setHeard(undefined);
          setOutcome(undefined);
          setProblem('');
        }}
      />
    );
  }

  const next = (): void => {
    setHeard(undefined);
    setOutcome(undefined);
    setProblem('');
    setIndex(index + 1);
  };

  return (
    <ModeScreen
      title={t('modes.sayIt')}
      ask={t('modes.sayAsk')}
      counts={false}
      progress={{ done: index, total: words.length }}
      said={
        outcome === 'correct'
          ? t('modes.sayRight', { word: word.headword })
          : outcome === 'wrong'
            ? t('modes.sayWrong', { word: word.headword })
            : problem
      }
      actions={
        outcome === undefined ? (
          <button type="button" className={styles.secondary} onClick={next}>
            {t('modes.skip')}
          </button>
        ) : (
          <button type="button" className={styles.primary} onClick={next}>
            {t('modes.next')}
          </button>
        )
      }
    >
      <div className={styles.prompt}>
        <span className={styles.promptText}>
          <Bilingual lang={meaningLang}>{word.meaning}</Bilingual>
        </span>
        {outcome === undefined && (
          <VoiceButton
            key={word.id}
            lang={lang}
            className={styles.speakBig}
            onHeard={onHeard}
            onProblem={setProblem}
          />
        )}
      </div>
      {problem !== '' && outcome === undefined && (
        <p className={`${styles.note} ${styles.noteBad}`}>{problem}</p>
      )}
      {heard !== undefined && <p className={styles.note}>{t('modes.sayHeard', { text: heard })}</p>}
      {outcome !== undefined && (
        <div className={styles.reveal}>
          <span className={styles.revealLabel}>
            {outcome === 'correct' ? t('session.correct') : t('modes.itWas')}
          </span>
          <span className={styles.revealWord}>
            <Bilingual lang={lang}>{word.headword}</Bilingual>
          </span>
        </div>
      )}
    </ModeScreen>
  );
}
